excels.excel:

EXPORT WITH SHEET="客户档案信息补录填报表", HEADER=true,
    MAPPING={"a":"客户编号","b":"客户名称","c":"客户类型","d":"信用等级","e":"联系人","f":"联系电话","g":"年采购额","h":"建档状态"},
    FORMAT={"g":"0"},
    FORMULAS={G8:'SUM(G2:G7)'},
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
